def darken_hex(hex_color: str, percentage: float) -> str:
    """
    Darken a hex color by the given percentage.

    Example:
        darken_hex("#6699CC", 20) -> "#527AA3"
    """
    if not 0 <= percentage <= 100:
        raise ValueError("Percentage must be between 0 and 100.")

    color = hex_color.lstrip("#")

    if len(color) == 3:
        color = "".join(char * 2 for char in color)
    elif len(color) != 6:
        raise ValueError("Color must be a 3- or 6-digit hex value.")

    try:
        red, green, blue = (
            int(color[i:i + 2], 16)
            for i in (0, 2, 4)
        )
    except ValueError:
        raise ValueError("Invalid hex color.")

    factor = 1 - percentage / 100

    darkened = (
        round(red * factor),
        round(green * factor),
        round(blue * factor),
    )

    return "#{:02X}{:02X}{:02X}".format(*darkened)


