from __future__ import annotations

import json
from dataclasses import MISSING, fields, is_dataclass
from datetime import date, datetime, time
from decimal import Decimal
from enum import Enum
from types import UnionType
from typing import (
    Any,
    Literal,
    Mapping,
    TypeVar,
    Union,
    get_args,
    get_origin,
    get_type_hints,
)
from uuid import UUID


T = TypeVar("T")


class RequestValidationError(ValueError):
    """Raised when a request body cannot be parsed into the requested model."""

    def __init__(self, message: str, *, path: str = "$") -> None:
        self.path = path
        self.message = message
        super().__init__(f"{path}: {message}")


def parse_request_body(body: str | bytes | bytearray | Mapping[str, Any], model: type[T]) -> T:
    """Parse and validate a request body into a typed dataclass model.

    ``body`` may be a JSON string, UTF-8 bytes, or an already-decoded mapping.

    Unknown fields, missing required fields, invalid types, and malformed JSON
    raise :class:`RequestValidationError`.

    Example::

        from dataclasses import dataclass

        @dataclass
        class CreateUser:
            name: str
            age: int
            enabled: bool = True

        user = parse_request_body(
            '{"name": "Ada", "age": 36}',
            CreateUser,
        )
    """
    if isinstance(body, (str, bytes, bytearray)):
        try:
            if isinstance(body, str):
                value = json.loads(body)
            else:
                value = json.loads(bytes(body).decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise RequestValidationError(f"invalid JSON: {exc}") from exc
    else:
        value = body

    return _convert_value(value, model, "$")


def _convert_value(value: Any, expected_type: Any, path: str) -> Any:
    if expected_type is Any:
        return value

    # Annotated[T, ...]
    if get_origin(expected_type) is not None and str(get_origin(expected_type)) == "typing.Annotated":
        expected_type = get_args(expected_type)[0]

    # NewType
    if hasattr(expected_type, "__supertype__"):
        expected_type = expected_type.__supertype__

    # Optional[T], Union[T, ...], and T | U
    origin = get_origin(expected_type)
    if origin in (Union, UnionType):
        if value is None and type(None) in get_args(expected_type):
            return None

        errors: list[str] = []
        for option in get_args(expected_type):
            if option is type(None):
                continue
            try:
                return _convert_value(value, option, path)
            except RequestValidationError as exc:
                errors.append(exc.message)

        raise RequestValidationError(
            f"value does not match any allowed type ({', '.join(errors)})",
            path=path,
        )

    if value is None:
        raise RequestValidationError("null is not allowed", path=path)

    # Literal["a", "b"], Literal[1, 2], ...
    if origin is Literal:
        allowed = get_args(expected_type)
        if value not in allowed or type(value) not in {type(item) for item in allowed}:
            raise RequestValidationError(
                f"expected one of {allowed!r}, got {value!r}",
                path=path,
            )
        return value

    # Dataclass model
    if isinstance(expected_type, type) and is_dataclass(expected_type):
        if not isinstance(value, Mapping):
            raise RequestValidationError("expected an object", path=path)

        return _convert_dataclass(value, expected_type, path)

    # Enum
    if isinstance(expected_type, type) and issubclass(expected_type, Enum):
        try:
            return expected_type(value)
        except ValueError as exc:
            valid_values = [member.value for member in expected_type]
            raise RequestValidationError(
                f"expected one of {valid_values!r}, got {value!r}",
                path=path,
            ) from exc

    # Containers
    if origin in (list,):
        if not isinstance(value, list):
            raise RequestValidationError("expected an array", path=path)

        item_type = get_args(expected_type)[0] if get_args(expected_type) else Any
        return [
            _convert_value(item, item_type, f"{path}[{index}]")
            for index, item in enumerate(value)
        ]

    if origin in (set, frozenset):
        if not isinstance(value, list):
            raise RequestValidationError("expected an array", path=path)

        item_type = get_args(expected_type)[0] if get_args(expected_type) else Any
        converted = [
            _convert_value(item, item_type, f"{path}[{index}]")
            for index, item in enumerate(value)
        ]
        return origin(converted)

    if origin is tuple:
        if not isinstance(value, list):
            raise RequestValidationError("expected an array", path=path)

        item_types = get_args(expected_type)

        # tuple[T, ...]
        if len(item_types) == 2 and item_types[1] is Ellipsis:
            return tuple(
                _convert_value(item, item_types[0], f"{path}[{index}]")
                for index, item in enumerate(value)
            )

        if len(value) != len(item_types):
            raise RequestValidationError(
                f"expected {len(item_types)} items, got {len(value)}",
                path=path,
            )

        return tuple(
            _convert_value(item, item_type, f"{path}[{index}]")
            for index, (item, item_type) in enumerate(zip(value, item_types))
        )

    if origin in (dict,):
        if not isinstance(value, Mapping):
            raise RequestValidationError("expected an object", path=path)

        key_type, value_type = get_args(expected_type) or (Any, Any)
        result = {}

        for key, item in value.items():
            converted_key = _convert_value(key, key_type, f"{path}.<key>")
            result[converted_key] = _convert_value(
                item,
                value_type,
                f"{path}.{key}",
            )

        return result

    # Scalar values
    if expected_type is bool:
        if type(value) is not bool:
            raise RequestValidationError("expected a boolean", path=path)
        return value

    if expected_type is int:
        if type(value) is not int:
            raise RequestValidationError("expected an integer", path=path)
        return value

    if expected_type is float:
        if type(value) not in (int, float):
            raise RequestValidationError("expected a number", path=path)
        return float(value)

    if expected_type is str:
        if not isinstance(value, str):
            raise RequestValidationError("expected a string", path=path)
        return value

    if expected_type is Decimal:
        if not isinstance(value, (str, int, float)) or isinstance(value, bool):
            raise RequestValidationError("expected a decimal value", path=path)
        try:
            return Decimal(str(value))
        except Exception as exc:
            raise RequestValidationError("invalid decimal value", path=path) from exc

    if expected_type is UUID:
        if not isinstance(value, str):
            raise RequestValidationError("expected a UUID string", path=path)
        try:
            return UUID(value)
        except ValueError as exc:
            raise RequestValidationError("invalid UUID", path=path) from exc

    if expected_type in (datetime, date, time):
        if not isinstance(value, str):
            raise RequestValidationError("expected an ISO-8601 string", path=path)
        try:
            if expected_type is datetime:
                return datetime.fromisoformat(value)
            if expected_type is date:
                return date.fromisoformat(value)
            return time.fromisoformat(value)
        except ValueError as exc:
            raise RequestValidationError(
                f"invalid {expected_type.__name__} value",
                path=path,
            ) from exc

    if isinstance(expected_type, type) and isinstance(value, expected_type):
        return value

    raise RequestValidationError(
        f"expected {getattr(expected_type, '__name__', expected_type)!s}, "
        f"got {type(value).__name__}",
        path=path,
    )


def _convert_dataclass(
    value: Mapping[str, Any],
    model: type[T],
    path: str,
) -> T:
    type_hints = get_type_hints(model)
    model_fields = {field.name: field for field in fields(model)}

    unknown_fields = set(value) - set(model_fields)
    if unknown_fields:
        unknown = ", ".join(sorted(map(str, unknown_fields)))
        raise RequestValidationError(
            f"unexpected field(s): {unknown}",
            path=path,
        )

    converted: dict[str, Any] = {}

    for name, field in model_fields.items():
        field_path = f"{path}.{name}"

        if name not in value:
            if field.default is not MISSING or field.default_factory is not MISSING:
                continue

            raise RequestValidationError("missing required field", path=field_path)

        converted[name] = _convert_value(
            value[name],
            type_hints.get(name, field.type),
            field_path,
        )

    try:
        return model(**converted)
    except TypeError as exc:
        raise RequestValidationError(str(exc), path=path) from exc

from argon2 import PasswordHasher
from argon2.exceptions import VerificationError, InvalidHashError

# These parameters are suitable starting values; benchmark and tune for your server.
password_hasher = PasswordHasher(
    time_cost=3,
    memory_cost=64 * 1024,  # 64 MiB
    parallelism=4,
    hash_len=32,
    salt_len=16,
)


def hash_password(password: str) -> str:
    """Return an Argon2id encoded hash suitable for database storage."""
    if not isinstance(password, str):
        raise TypeError("password must be a string")

    return password_hasher.hash(password)


def verify_password(password: str, stored_hash: str) -> bool:
    """Verify a password against its stored hash."""
    if not isinstance(password, str) or not isinstance(stored_hash, str):
        return False

    try:
        return password_hasher.verify(stored_hash, password)
    except (VerificationError, InvalidHashError):
        # Includes wrong passwords and malformed hashes.
        return False


def needs_rehash(stored_hash: str) -> bool:
    """Check whether the hash should be upgraded to current parameters."""
    try:
        return password_hasher.check_needs_rehash(stored_hash)
    except (VerificationError, InvalidHashError):
        return True

