from __future__ import annotations

import json
from collections.abc import Iterable, Mapping, Sequence
from typing import Any, TextIO


def _format_cell(value: Any) -> str:
    """Convert a record value into a single printable table cell."""
    if value is None:
        return ""

    if isinstance(value, (dict, list, tuple)):
        value = json.dumps(value, ensure_ascii=False, separators=(",", ":"))

    # Keep multiline values from breaking the table layout.
    return str(value).replace("\n", "\\n").replace("\r", "\\r")


def format_table(
    records: Iterable[Mapping[str, Any]],
    columns: Sequence[str] | None = None,
) -> str:
    """Format records as an aligned plain-text table.

    Column order is taken from the first appearance of each key unless
    ``columns`` is provided explicitly.
    """
    rows = list(records)

    if columns is None:
        column_names: list[str] = []
        seen: set[str] = set()

        for record in rows:
            if not isinstance(record, Mapping):
                raise TypeError("table records must be mappings")

            for key in record:
                key = str(key)
                if key not in seen:
                    seen.add(key)
                    column_names.append(key)
    else:
        column_names = [str(column) for column in columns]

        for record in rows:
            if not isinstance(record, Mapping):
                raise TypeError("table records must be mappings")

    if not column_names:
        return ""

    rendered_rows = [
        [_format_cell(record.get(column, "")) for column in column_names]
        for record in rows
    ]

    widths = [
        max(
            len(column_names[index]),
            *(len(row[index]) for row in rendered_rows),
        )
        for index in range(len(column_names))
    ]

    def render_row(row: Sequence[str]) -> str:
        return " | ".join(
            value.ljust(width)
            for value, width in zip(row, widths)
        )

    header = render_row(column_names)
    separator = "-+-".join("-" * width for width in widths)

    lines = [header, separator]
    lines.extend(render_row(row) for row in rendered_rows)

    return "\n".join(lines)


def print_table(
    records: Iterable[Mapping[str, Any]],
    columns: Sequence[str] | None = None,
    *,
    file: TextIO | None = None,
) -> None:
    """Print records as an aligned table."""
    import sys

    if file is None:
        file = sys.stdout

    output = format_table(records, columns=columns)
    if output:
        print(output, file=file)

