def add_table_command(subparsers: argparse._SubParsersAction) -> None:
    parser = subparsers.add_parser(
        "table",
        help="print JSON records as an aligned table",
    )
    parser.add_argument(
        "input",
        nargs="?",
        default="-",
        help="JSON file to read, or - for stdin",
    )
    parser.add_argument(
        "--columns",
        help="comma-separated list of columns to display",
    )

    def run_table(args: argparse.Namespace) -> None:
        columns = None
        if args.columns:
            columns = [
                column.strip()
                for column in args.columns.split(",")
                if column.strip()
            ]

        table_command(args.input, columns=columns)

    parser.set_defaults(command_handler=run_table)

