def get_value(key, default=None, filename=".env"):
    for line in Path(filename).read_text().splitlines():
        line = line.strip()

        if not line or line.startswith("#") or "=" not in line:
            continue

        name, value = line.split("=", 1)
        if name.strip() == key:
            return value.strip().strip("\"'")

    return default


