from collections.abc import Iterable, Mapping
from typing import Any


def _display_value(value: Any) -> str:
    """Convert a value into a single-line string for table output."""
    if value is None:
        return ""

    return str(value).replace("\n", " ").replace("\r", " ")


def format_table(records: Iterable[Mapping[str, Any]]) -> str:
    """Return records formatted as an aligned ASCII table."""
    records = list(records)

    if not records:
        return "No records."

    # Preserve the order in which columns first appear.
    columns: list[str] = []
    seen: set[str] = set()

    for record in records:
        for key in record:
            column = str(key)
            if column not in seen:
                columns.append(column)
                seen.add(column)

    if not columns:
        return "No records."

    rows: list[list[str]] = [
        [_display_value(record.get(column, "")) for column in columns]
        for record in records
    ]

    widths = [
        max(
            len(column),
            *(len(row[index]) for row in rows),
        )
        for index, column in enumerate(columns)
    ]

    header = " | ".join(
        column.ljust(width)
        for column, width in zip(columns, widths)
    )

    separator = "-+-".join("-" * width for width in widths)

    body = [
        " | ".join(
            value.ljust(width)
            for value, width in zip(row, widths)
        )
        for row in rows
    ]

    return "\n".join([header, separator, *body])


def print_table(records: Iterable[Mapping[str, Any]]) -> None:
    """Print records as an aligned table."""
    print(format_table(records))

def darken_color(hex_color: str, percentage: float) -> str:
    """
    Darken a hexadecimal color by a percentage.

    Args:
        hex_color: A 3- or 6-digit hex color, with or without '#'.
        percentage: Amount to darken, from 0 to 100.

    Returns:
        The darkened color as a 6-digit hex string prefixed with '#'.

    Examples:
        >>> darken_color("#6699CC", 20)
        '#527AA3'
        >>> darken_color("fff", 50)
        '#808080'
    """
    if not isinstance(hex_color, str):
        raise TypeError("hex_color must be a string")

    if not 0 <= percentage <= 100:
        raise ValueError("percentage must be between 0 and 100")

    value = hex_color.strip().lstrip("#")

    if len(value) == 3:
        value = "".join(char * 2 for char in value)
    elif len(value) != 6:
        raise ValueError("hex_color must contain 3 or 6 hexadecimal digits")

    try:
        red, green, blue = (
            int(value[index:index + 2], 16)
            for index in (0, 2, 4)
        )
    except ValueError as exc:
        raise ValueError("hex_color contains invalid hexadecimal characters") from exc

    factor = 1 - (percentage / 100)

    darkened = (
        round(channel * factor)
        for channel in (red, green, blue)
    )

    return "#{:02x}{:02x}{:02x}".format(*darkened)

