def darken_hex(hex_color: str, percentage: float) -> str:
    """Darken a hex colour by the given percentage."""
    if not 0 <= percentage <= 100:
        raise ValueError("percentage must be between 0 and 100")

    hex_color = hex_color.lstrip("#")

    # Support shorthand colours such as #abc
    if len(hex_color) == 3:
        hex_color = "".join(ch * 2 for ch in hex_color)

    if len(hex_color) != 6:
        raise ValueError("hex_color must be in #RGB or #RRGGBB format")

    factor = 1 - percentage / 100

    rgb = [
        round(int(hex_color[i:i + 2], 16) * factor)
        for i in range(0, 6, 2)
    ]

    return "#" + "".join(f"{channel:02x}" for channel in rgb)

