from __future__ import annotations

import json
from collections.abc import Iterable, Mapping
from typing import Any


def _format_cell(value: Any) -> str:
    """Convert a record value into a single printable table cell."""
    if value is None:
        return ""

    if isinstance(value, (dict, list, tuple)):
        value = json.dumps(value, ensure_ascii=False, sort_keys=True)

    return str(value).replace("\r\n", " ").replace("\n", " ").replace("\r", " ")


def format_table(
    records: Iterable[Mapping[str, Any]],
    *,
    columns: Iterable[str] | None = None,
    header: bool = True,
) -> str:
    """Return records formatted as an aligned terminal table.

    Columns are inferred from the first appearance of keys when not supplied.
    """
    records = list(records)

    for record in records:
        if not isinstance(record, Mapping):
            raise TypeError("table records must be mappings")

    if columns is None:
        names: list[str] = []
        seen: set[str] = set()

        for record in records:
            for key in record:
                key = str(key)
                if key not in seen:
                    names.append(key)
                    seen.add(key)
    else:
        names = [str(column) for column in columns]

    if not names:
        return ""

    rows = [
        [_format_cell(record.get(column, "")) for column in names]
        for record in records
    ]

    widths = [
        max(
            len(name),
            *(len(row[index]) for row in rows),
        )
        for index, name in enumerate(names)
    ]

    def render_row(row: list[str]) -> str:
        # Do not pad the final column, avoiding trailing whitespace.
        cells = [
            value.ljust(widths[index])
            for index, value in enumerate(row)
        ]
        return "  ".join(cells).rstrip()

    output: list[str] = []

    if header:
        output.append(render_row(names))
        output.append("  ".join("-" * width for width in widths))

    output.extend(render_row(row) for row in rows)

    return "\n".join(output)


def print_table(
    records: Iterable[Mapping[str, Any]],
    *,
    columns: Iterable[str] | None = None,
    header: bool = True,
) -> None:
    """Print records as an aligned terminal table."""
    rendered = format_table(records, columns=columns, header=header)
    if rendered:
        print(rendered)

