from phonenumbers import NumberParseException, PhoneNumberFormat


def validate_and_format_phone(raw_number: str, default_region: str | None = None):
    """
    default_region is an ISO 3166-1 alpha-2 code, such as "US", "GB", or "AU".
    It is needed when raw_number does not include a country code.
    """
    try:
        number = phonenumbers.parse(raw_number, default_region)
    except NumberParseException as exc:
        return {
            "valid": False,
            "error": str(exc),
        }

    if not phonenumbers.is_possible_number(number):
        return {
            "valid": False,
            "error": "Number has an impossible length or prefix",
        }

    if not phonenumbers.is_valid_number(number):
        return {
            "valid": False,
            "error": "Number is not valid for its region",
        }

    return {
        "valid": True,

        # Canonical international format, suitable for storage/API use
        "e164": phonenumbers.format_number(
            number, PhoneNumberFormat.E164
        ),

        # Human-readable international format
        "international": phonenumbers.format_number(
            number, PhoneNumberFormat.INTERNATIONAL
        ),
    }

