from __future__ import annotations

import json
import types
from dataclasses import MISSING, fields, is_dataclass
from enum import Enum
from typing import Any, Mapping, TypeVar, Union, get_args, get_origin, get_type_hints
from uuid import UUID


T = TypeVar("T")


class RequestBodyError(ValueError):
    """Raised when a request body cannot be parsed into the requested model."""


def parse_request_body(
    body: bytes | bytearray | str | Mapping[str, Any],
    model: type[T],
) -> T:
    """Parse and validate a JSON request body into a dataclass model.

    Args:
        body: JSON bytes, JSON text, or an already-decoded mapping.
        model: Dataclass type to instantiate.

    Returns:
        An instance of ``model``.

    Raises:
        RequestBodyError: If the body is malformed or does not match ``model``.
        TypeError: If ``model`` is not a dataclass.
    """
    if not is_dataclass(model):
        raise TypeError("model must be a dataclass type")

    data = _decode_body(body)

    if not isinstance(data, Mapping):
        raise RequestBodyError("request body must contain a JSON object")

    try:
        return _build_dataclass(data, model, path="$")
    except RequestBodyError:
        raise
    except Exception as exc:
        raise RequestBodyError(f"$: invalid request body: {exc}") from exc


def _decode_body(
    body: bytes | bytearray | str | Mapping[str, Any],
) -> Any:
    if isinstance(body, Mapping):
        return body

    if isinstance(body, (bytes, bytearray)):
        try:
            body = body.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise RequestBodyError("request body is not valid UTF-8") from exc

    if not isinstance(body, str):
        raise RequestBodyError(
            "request body must be bytes, text, or a mapping"
        )

    try:
        return json.loads(body)
    except json.JSONDecodeError as exc:
        raise RequestBodyError(
            f"invalid JSON at line {exc.lineno}, column {exc.colno}: {exc.msg}"
        ) from exc


def _build_dataclass(
    data: Mapping[str, Any],
    model: type[T],
    *,
    path: str,
) -> T:
    hints = get_type_hints(model)
    model_fields = {
        field.name: field
        for field in fields(model)
        if field.init
    }

    unknown = set(data) - set(model_fields)
    if unknown:
        names = ", ".join(sorted(map(str, unknown)))
        raise RequestBodyError(f"{path}: unexpected field(s): {names}")

    values: dict[str, Any] = {}

    for name, field in model_fields.items():
        field_path = f"{path}.{name}"

        if name not in data:
            if field.default is MISSING and field.default_factory is MISSING:
                raise RequestBodyError(f"{field_path}: field is required")
            continue

        annotation = hints.get(name, field.type)
        values[name] = _validate_value(
            data[name],
            annotation,
            path=field_path,
        )

    try:
        return model(**values)
    except TypeError as exc:
        raise RequestBodyError(f"{path}: {exc}") from exc


def _validate_value(value: Any, annotation: Any, *, path: str) -> Any:
    if annotation is Any:
        return value

    origin = get_origin(annotation)
    args = get_args(annotation)

    # Annotated[T, ...]
    if origin is not None and str(origin) == "<class 'typing.Annotated'>":
        return _validate_value(value, args[0], path=path)

    # Optional[T], Union[T, ...], and T | None
    if origin in (Union, types.UnionType):
        if value is None and type(None) in args:
            return None

        errors = []
        for option in args:
            if option is type(None):
                continue
            try:
                return _validate_value(value, option, path=path)
            except RequestBodyError as exc:
                errors.append(str(exc))

        expected = " or ".join(_type_name(option) for option in args)
        raise RequestBodyError(
            f"{path}: expected {expected}, got {_value_name(value)}"
        )

    # Literal["draft", "published"], etc.
    if origin is __import__("typing").Literal:
        if value not in args:
            raise RequestBodyError(
                f"{path}: expected one of {args!r}, got {value!r}"
            )
        return value

    # Nested dataclass
    if isinstance(annotation, type) and is_dataclass(annotation):
        if not isinstance(value, Mapping):
            raise RequestBodyError(
                f"{path}: expected an object, got {_value_name(value)}"
            )
        return _build_dataclass(value, annotation, path=path)

    # Enum values are represented by their JSON values.
    if isinstance(annotation, type) and issubclass(annotation, Enum):
        try:
            return annotation(value)
        except ValueError as exc:
            allowed = [member.value for member in annotation]
            raise RequestBodyError(
                f"{path}: expected one of {allowed!r}, got {value!r}"
            ) from exc

    if annotation is UUID:
        if not isinstance(value, str):
            raise RequestBodyError(f"{path}: expected a UUID string")
        try:
            return UUID(value)
        except ValueError as exc:
            raise RequestBodyError(f"{path}: invalid UUID") from exc

    # list[T], set[T], tuple[T, ...]
    if origin in (list, set, tuple):
        if not isinstance(value, list):
            raise RequestBodyError(
                f"{path}: expected an array, got {_value_name(value)}"
            )

        if origin is tuple and len(args) == 2 and args[1] is Ellipsis:
            item_type = args[0]
            result = tuple(
                _validate_value(item, item_type, path=f"{path}[{index}]")
                for index, item in enumerate(value)
            )
            return result

        item_type = args[0] if args else Any
        result = [
            _validate_value(item, item_type, path=f"{path}[{index}]")
            for index, item in enumerate(value)
        ]

        if origin is set:
            return set(result)
        if origin is tuple:
            return tuple(result)
        return result

    # dict[K, V]
    if origin is dict:
        if not isinstance(value, dict):
            raise RequestBodyError(
                f"{path}: expected an object, got {_value_name(value)}"
            )

        key_type, value_type = args or (Any, Any)
        result = {}

        for key, item in value.items():
            validated_key = _validate_value(
                key,
                key_type,
                path=f"{path}[{key!r}]",
            )
            result[validated_key] = _validate_value(
                item,
                value_type,
                path=f"{path}[{key!r}]",
            )

        return result

    # JSON booleans must not be accepted as integers.
    if annotation is bool:
        valid = type(value) is bool
    elif annotation is int:
        valid = type(value) is int
    elif annotation is float:
        valid = type(value) in (int, float)
    elif annotation is str:
        valid = type(value) is str
    else:
        valid = isinstance(value, annotation)

    if not valid:
        raise RequestBodyError(
            f"{path}: expected {_type_name(annotation)}, "
            f"got {_value_name(value)}"
        )

    if annotation is float and isinstance(value, int):
        return float(value)

    return value


def _type_name(annotation: Any) -> str:
    if annotation is Any:
        return "any"
    return getattr(annotation, "__name__", str(annotation))


def _value_name(value: Any) -> str:
    if value is None:
        return "null"
    return type(value).__name__

