    try:
        body = await request.json()
    except (JSONDecodeError, UnicodeDecodeError, ValueError) as exc:
        raise HTTPException(
            status_code=422,
            detail="Request body must contain valid JSON.",
        ) from exc

    return validate_body(body, model_type)

