from email import policy
from email.header import decode_header
from email.parser import BytesParser


def _decode_header(value: object | None) -> str:
    """Decode an RFC 2047 email header into readable text."""
    if value is None:
        return ""

    decoded: list[str] = []

    for part, charset in decode_header(str(value)):
        if isinstance(part, bytes):
            decoded.append(
                part.decode(charset or "ascii", errors="replace")
            )
        else:
            decoded.append(part)

    return "".join(decoded).strip()


def extract_sender_subject(raw_message: bytes | str) -> dict[str, str]:
    """Extract the sender and subject from a raw email message.

    Args:
        raw_message: An RFC 5322 email message as bytes or text.

    Returns:
        A dictionary containing ``sender`` and ``subject``.
    """
    if isinstance(raw_message, str):
        raw_message = raw_message.encode("utf-8")

    message = BytesParser(policy=policy.default).parsebytes(raw_message)

    return {
        "sender": _decode_header(message.get("From")),
        "subject": _decode_header(message.get("Subject")),
    }

