import ast
import os
from pathlib import Path


def get_env_value(
    key: str,
    default: str | None = None,
    env_file: str | Path = ".env",
) -> str | None:
    """Return a configuration value from the environment or a .env file.

    Existing environment variables take precedence over values in the .env
    file. If the key cannot be found, ``default`` is returned.
    """
    if not key:
        raise ValueError("Environment variable key cannot be empty")

    # Allow real environment variables to override .env values.
    if key in os.environ:
        return os.environ[key]

    path = Path(env_file)

    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except FileNotFoundError:
        return default

    for line in lines:
        line = line.strip()

        if not line or line.startswith("#"):
            continue

        if line.startswith("export "):
            line = line[7:].lstrip()

        name, separator, value = line.partition("=")
        if not separator or name.strip() != key:
            continue

        value = value.strip()

        # Support quoted values, such as KEY="hello world".
        if len(value) >= 2 and value[0] == value[-1] and value[0] in {"'", '"'}:
            try:
                return ast.literal_eval(value)
            except (SyntaxError, ValueError):
                return value[1:-1]

        # Remove unquoted inline comments.
        if " #" in value:
            value = value.split(" #", 1)[0].rstrip()

        return value

    return default

