from __future__ import annotations

import re


_PHONE_SEPARATORS = " -()."


def _phone_digits(value: str) -> str:
    """Remove common phone-number formatting characters."""
    if not isinstance(value, str):
        raise TypeError("phone number must be a string")

    value = value.strip()
    if not value:
        raise ValueError("phone number cannot be empty")

    if value.startswith("+"):
        value = value[1:]
    elif value.startswith("00"):
        value = value[2:]

    if "+" in value:
        raise ValueError("international prefix must appear only at the start")

    if any(character not in "0123456789" + _PHONE_SEPARATORS for character in value):
        raise ValueError("phone number contains invalid characters")

    if value.count("(") != value.count(")"):
        raise ValueError("phone number has unmatched parentheses")

    digits = re.sub(r"[^\d]", "", value)

    if not digits:
        raise ValueError("phone number must contain digits")

    return digits


def format_phone_number(
    number: str,
    *,
    country_code: str | None = None,
) -> str:
    """Validate and return a phone number in E.164 format.

    E.164 format is a leading ``+`` followed by 7–15 digits, for example:
    ``+14155552671``.

    Numbers beginning with ``+`` or ``00`` are treated as international
    numbers. For a national number, ``country_code`` must be supplied.
    """
    if not isinstance(number, str):
        raise TypeError("phone number must be a string")

    original = number.strip()
    is_international = original.startswith("+") or original.startswith("00")
    digits = _phone_digits(original)

    if not is_international:
        if country_code is None:
            raise ValueError(
                "national phone numbers require a country code"
            )

        country_digits = _phone_digits(country_code)

        if len(country_digits) > 3 or country_digits.startswith("0"):
            raise ValueError("country code must contain 1–3 digits")

        # Remove one common national trunk prefix, such as the 0 in 020...
        if digits.startswith("0"):
            digits = digits[1:]

        digits = country_digits + digits

    if digits.startswith("0"):
        raise ValueError("international phone number cannot start with 0")

    if not 7 <= len(digits) <= 15:
        raise ValueError(
            "international phone number must contain between 7 and 15 digits"
        )

    return f"+{digits}"


def validate_phone_number(
    number: str,
    *,
    country_code: str | None = None,
) -> bool:
    """Return whether a phone number can be formatted as E.164."""
    try:
        format_phone_number(number, country_code=country_code)
    except (TypeError, ValueError):
        return False
    return True

