    def cell(value: Any) -> str:
        # Keep a record on one terminal line.
        return str(value if value is not None else "").replace("\n", "\\n")

    values = [
        [cell(record.get(column, "")) for column in columns]
        for record in rows
    ]

    widths = [
        max(len(column), *(len(row[index]) for row in values))
        for index, column in enumerate(columns)
    ]

    def render_row(row: list[str]) -> str:
        return " | ".join(
            value.ljust(width)
            for value, width in zip(row, widths)
        )

    separator = "-+-".join("-" * width for width in widths)

    output = [
        render_row(columns),
        separator,
        *(render_row(row) for row in values),
    ]

    print("\n".join(output))

