def normalize(value: str) -> str:
    """
    Normalize a string for comparison.

    Handles:
    - Leading/trailing whitespace
    - Case differences
    - Accented characters
    - Repeated whitespace
    """
    value = unicodedata.normalize("NFKD", value)
    value = "".join(char for char in value if not unicodedata.combining(char))
    return " ".join(value.casefold().split())


def closest_match(query: str, names: Sequence[str]) -> str | None:
    """
    Return the name most similar to query.

    Returns None if names is empty.
    """
    if not names:
        return None

    normalized_query = normalize(query)

    if not normalized_query:
        raise ValueError("query must not be empty")

    best_name = names[0]
    best_score = -1.0

    for name in names:
        normalized_name = normalize(name)

        # Prefer an exact normalized match immediately.
        if normalized_name == normalized_query:
            return name

        score = SequenceMatcher(
            None,
            normalized_query,
            normalized_name,
        ).ratio()

        # `>` keeps the first name when scores are tied.
        if score > best_score:
            best_score = score
            best_name = name

    return best_name


