@app.post("/match", response_model=MatchResponse)
def match_name(request: MatchRequest) -> MatchResponse:
    try:
        match = closest_match(request.query, request.names)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc

    if match is None:
        raise HTTPException(
            status_code=422,
            detail="names must contain at least one value",
        )

    return MatchResponse(match=match)

